mapper.update:
UPDATE pcd_im_group
SET announcement = #{announcement}, update_time = NOW()
WHERE group_id = #{groupId}

UPDATE pcd_im_group
SET member_count = member_count + 1, update_time = NOW()
WHERE group_id = #{groupId}

UPDATE pcd_im_group
SET member_count = GREATEST(member_count - 1, 0), update_time = NOW()
WHERE group_id = #{groupId}

UPDATE pcd_im_group
SET is_all_muted = #{isAllMuted}, update_time = NOW()
WHERE group_id = #{groupId}

UPDATE pcd_im_group
SET status = 1, update_time = NOW()
WHERE group_id = #{groupId}
